var Pool = import_pg.default.Pool || import_pg.default.default?.Pool;
var createPool = () => {
  const user = process.env.SQL_USER || process.env.SQL_ADMIN_USER;
  const password = process.env.SQL_PASSWORD || process.env.SQL_ADMIN_PASSWORD;
  return new Pool({
    host: process.env.SQL_HOST,
    port: process.env.SQL_PORT ? parseInt(process.env.SQL_PORT, 10) : 5432,
    user,
    password,
    database: process.env.SQL_DB_NAME,
    max: 10,
    idleTimeoutMillis: 30000,
    connectionTimeoutMillis: 1e4,
    keepAlive: true,
    keepAliveInitialDelayMillis: 1e4,
    allowExitOnIdle: false
  });
};
var pool = createPool();
pool.on("error", (err) => {
  console.warn("SQL client connection reset or idle timeout (auto-recovering):", err?.message || err);
});
var db = import_node_postgres.drizzle(pool, { schema: exports_schema });
async function withDbRetry(operation, maxRetries = 2) {
  let attempt = 0;
  while (true) {
    try {
      return await operation();
    } catch (err) {
      attempt++;
      const errMsg = err?.message || String(err);
      const isConnectionError = errMsg.includes("Connection terminated") || errMsg.includes("connection closed") || errMsg.includes("ECONNRESET") || errMsg.includes("timeout") || errMsg.includes("Client has encountered a connection error");
      if (attempt <= maxRetries && isConnectionError) {
        console.warn(`[DB Retry] Retrying query after connection glitch (attempt ${attempt}/${maxRetries}):`, errMsg);
        await new Promise((resolve) => setTimeout(resolve, 150 * attempt));
        continue;
      }
      throw err;
    }
  }
}

