// src/utils/shadowing.ts
function validShadowingTimings(cue) {
  if (!Array.isArray(cue.timings) || !cue.timings.length || cue.start === null || cue.end === null)
    return false;
  let previousOffset = 0;
  let previousTime = cue.start;
  return cue.timings.every((t) => {
    if (!t || !Number.isInteger(t.textStart) || !Number.isInteger(t.textEnd) || t.textStart < previousOffset || t.textEnd <= t.textStart || cue.text.slice(t.textStart, t.textEnd) !== t.text || !Number.isFinite(t.start) || !Number.isFinite(t.end) || t.start < previousTime || t.end < t.start || t.end > cue.end + 0.001)
      return false;
    previousOffset = t.textEnd;
    previousTime = t.end;
    return true;
  }) && cue.text.replace(/\s/g, "") === cue.timings.map((t) => t.text).join("").replace(/\s/g, "");
}
function normalizeShadowingTimeline(cues) {
  const sorted = cues.map((cue) => ({ ...cue })).sort((a, b) => (a.start ?? Infinity) - (b.start ?? Infinity));
  return sorted.map((cue, index) => {
    if (cue.start === null || cue.end === null)
      return cue;
    if (validShadowingTimings(cue))
      return cue;
    const next = sorted.slice(index + 1).find((item) => item.start !== null && item.start > cue.start);
    return { ...cue, end: next?.start !== undefined && next.start !== null ? Math.min(cue.end, next.start) : cue.end };
  });
}

// src/server/shadowingNativeTiming.ts
function parseYouTubeWordCaptions(xml) {
  if (!xml.includes("<timedtext") || xml.length > 2000000)
    return [];
  const $ = import_cheerio.load(xml, { xml: true });
  const cues = [];
  $("body > p").each((_, element) => {
    const p = $(element);
    if (p.attr("a") === "1" || !p.attr("t") || !p.attr("d"))
      return;
    const start = Number(p.attr("t")) / 1000;
    const end = start + Number(p.attr("d")) / 1000;
    const text = p.text().trim();
    if (!text || text.length > 1000 || !Number.isFinite(start) || start < 0 || !Number.isFinite(end) || end <= start)
      return;
    const cue = { id: `youtube-${cues.length}`, text, start, end };
    const segments = p.children("s").toArray();
    if (segments.length > 1 && segments.some((s) => $(s).attr("t") !== undefined)) {
      let offset = 0;
      const timings = segments.map((s, i) => {
        const segment = $(s);
        const word = segment.text();
        const onset = start + (i === 0 && segment.attr("t") === undefined ? 0 : Number(segment.attr("t") ?? NaN) / 1000);
        const timing = { text: word, textStart: offset, textEnd: offset + word.length, start: onset, end: onset };
        offset += word.length;
        return timing;
      });
      if (validShadowingTimings({ ...cue, timings }))
        cue.timings = timings;
    }
    cues.push(cue);
  });
  const result = cues.slice(0, 500).sort((a, b) => a.start - b.start);
  result.forEach((cue, i) => {
    const next = result.slice(i + 1).find((item) => item.start > cue.start);
    if (next)
      cue.end = Math.min(cue.end, next.start);
    if (cue.timings && !validShadowingTimings(cue))
      delete cue.timings;
  });
  return result;
}

