function parseManagedCaptions(data) {
  if (!/^ja(?:-|$)/.test(data?.lang || "") || !Array.isArray(data.content))
    throw new Error("Japanese captions unavailable");
  const cues = data.content.filter((c) => c && typeof c.text === "string" && c.text.trim() && Number.isFinite(c.offset) && c.offset >= 0 && Number.isFinite(c.duration) && c.duration > 0 && (!c.lang || /^ja(?:-|$)/.test(c.lang))).slice(0, 500).map((c, index) => ({ id: `managed-${index}`, text: c.text.replace(/<[^>]*>/g, "").slice(0, 1000), start: c.offset / 1000, end: (c.offset + c.duration) / 1000 }));
  if (!cues.length)
    throw new Error("Japanese captions unavailable");
  return cues.sort((a, b) => a.start - b.start);
}
async function fetchManagedCaptions(videoId) {
  const url = new URL("https://api.supadata.ai/v1/transcript");
  url.searchParams.set("url", `https://www.youtube.com/watch?v=${videoId}`);
  url.searchParams.set("lang", "ja");
  url.searchParams.set("text", "false");
  url.searchParams.set("mode", "native");
  const response = await fetch(url, { headers: { "x-api-key": process.env.SUPADATA_API_KEY }, signal: AbortSignal.timeout(20000) });
  if (response.status === 202)
    throw new Error("Caption provider is still processing");
  if (!response.ok)
    throw new Error(`Caption provider returned ${response.status}`);
  return parseManagedCaptions(await response.json());
}
